test("merge undo scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-A", "3");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "grace-C", "2");
  await ui.setSetting(pg_uma, "proof-threshold-A", "0.50");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-10", "half-even")).toBe(true);
  await ui.setSetting(pg_uma, "review-threshold", "1.50");
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "pending-sla", "1");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33", "from": "2026-03-10"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "terms": "20", "contact": "ben@x"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "tags": "a"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "tags": "c"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "50.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "50.00"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Ada", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  expect(await ui.addCrew(pg_uma, "C1", "Ada")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ben")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Cam")).toBe(true);
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "12.50", "start": "2026-03-01", "end": "2026-04-30", "every": "10"}));
  expect(await ui.inlineGrade(pg_uma, p_ada, "C")).toBe(true);
  await ui.expectAuditView(pg_uma, "Cam", [
    `CREW_MEMBER_ADDED sheet=${sheet} by=uma crew=C1 name=Cam`,
    `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=n/a overdue-total=0.00`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=C`
  ]);
  expect(await ui.retire(pg_uma, p_ben, "2026-03-15")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.pasteClaims(pg_uma, "Cam,12.50,,a, b\nAda,x,,paste\nBen,0.40,2026-02-10,a, b")).toBeNull();
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "3.33", "date": "2026-03-05", "note": "n"}));
  expect(await ui.generatePlans(pg_uma)).toBe(2);
  const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
  const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
  expect(await ui.addProof(pg_uma, c_cam_0, "photo")).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-due")).toHaveText("2.50");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("2.50");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-0-30")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-31-60")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-61")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("3");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-REVIEW-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-crew-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-reviews-count")).toHaveText("0");
